// UploadAssemblyFile transfers one fixed-size file, not its Assembly's processing result.
func (client *Client) UploadAssemblyFile(ctx context.Context, input AssemblyUploadOptions) (*AssemblyUploadSession, error) {
	return client.runTusUpload(ctx, input, nil)
}

// ResumeAssemblyFile resumes the same file from the server offset using a saved session.
func (client *Client) ResumeAssemblyFile(ctx context.Context, input AssemblyUploadOptions, session AssemblyUploadSession) (*AssemblyUploadSession, error) {
	return client.runTusUpload(ctx, input, &session)
}
func workflowCollection(status *AssemblyWorkflowResult) string { return status.GetTusUrl() }
